CREATE TABLE IF NOT EXISTS public.mcp_receipts (receipt_id TEXT PRIMARY KEY, spec TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), intent JSONB NOT NULL, execution_state TEXT NOT NULL, wrapped_server TEXT NOT NULL, result_hash TEXT NOT NULL, authority_root TEXT NOT NULL, physical_gate TEXT NOT NULL DEFAULT 'ACTION_REQUIRED', license TEXT NOT NULL DEFAULT 'Apache-2.0', the_central_rule TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_mcp_receipts_root ON public.mcp_receipts(authority_root);
CREATE INDEX IF NOT EXISTS idx_mcp_receipts_created ON public.mcp_receipts(created_at DESC);
ALTER TABLE public.mcp_receipts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_full_access ON public.mcp_receipts;
CREATE POLICY service_role_full_access ON public.mcp_receipts FOR ALL TO service_role USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS public_read_receipts ON public.mcp_receipts;
CREATE POLICY public_read_receipts ON public.mcp_receipts FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS no_deletes ON public.mcp_receipts;
CREATE POLICY no_deletes ON public.mcp_receipts FOR DELETE USING (false);
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='mcp_receipts') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.mcp_receipts; END IF; END $$;
